WITH matched_keys AS (SELECT method, status FROM payments INTERSECT ALL SELECT method, status FROM payments WHERE status <> 'REFUNDED'), reconciled AS (SELECT s.* FROM payments s INNER JOIN matched_keys k ON s.method = k.method AND s.status = k.status), with_windows AS (SELECT id, method, amount, status, ROUND(amount / SUM(amount) OVER (PARTITION BY status), 4) AS amount_share, SUM(amount) OVER (PARTITION BY status ORDER BY CAST(paid_at AS BIGINT) RANGE BETWEEN 2592000 PRECEDING AND CURRENT ROW) AS amount_sum_30d, MAX(amount) OVER (ORDER BY CAST(paid_at AS BIGINT) RANGE BETWEEN 2592000 PRECEDING AND CURRENT ROW) AS amount_max_30d FROM reconciled), enriched AS (SELECT *, ROUND(amount / SUM(amount) OVER (PARTITION BY method), 4) AS amount_share_2, AVG(amount_sum_30d) OVER (PARTITION BY status) AS status_avg_amount_sum_30d FROM with_windows), metrics AS (SELECT id, method, AVG(amount_share) OVER (PARTITION BY status, method) AS status_avg_amount_share, SUM(amount_max_30d) OVER (PARTITION BY status) AS status_sum_amount_max_30d FROM enriched), enriched_payments AS (SELECT id, method, status_avg_amount_share, ROUND(status_sum_amount_max_30d / SUM(status_sum_amount_max_30d) OVER (PARTITION BY method), 4) AS status_sum_amount_max_30d_share, CUME_DIST() OVER (PARTITION BY method ORDER BY status_sum_amount_max_30d NULLS FIRST) AS status_sum_amount_max_30d_cume_dist FROM metrics) SELECT CASE WHEN status_sum_amount_max_30d_share >= 0.9 THEN 'LARGE' ELSE 'SMALL' END AS status_sum_amount_max_30d_share_tier, SORT_ARRAY(COLLECT_SET(method)) AS method_list, COUNT(DISTINCT method) AS distinct_methods, APPROX_PERCENTILE(status_sum_amount_max_30d_cume_dist, ARRAY(0.25, 0.5, 0.75)) AS status_sum_amount_max_30d_cume_dist_quartiles, APPROX_PERCENTILE(status_avg_amount_share, ARRAY(0.25, 0.5, 0.75)) AS status_avg_amount_share_quartiles, SUM(CASE WHEN method = 'cash' THEN status_sum_amount_max_30d_share ELSE 0 END) AS cash_status_sum_amount_max_30d_share, GROUPING_ID() AS grouping_level FROM enriched_payments GROUP BY ROLLUP (CASE WHEN status_sum_amount_max_30d_share >= 0.9 THEN 'LARGE' ELSE 'SMALL' END) HAVING cash_status_sum_amount_max_30d_share > 0
